begin;
create table platform.organizations (id uuid primary key default gen_random_uuid(), slug text not null unique check (slug = lower(slug)), display_name text not null, legal_name text, organization_type text not null check (organization_type in ('platform_owner','customer')), status text not null default 'active' check (status in ('pending','active','suspended','archived')), billing_exempt boolean not null default false, timezone text not null default 'Africa/Nairobi', currency_code char(3) not null default 'KES', metadata jsonb not null default '{}', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), archived_at timestamptz);
create unique index one_platform_owner_organization on platform.organizations ((organization_type)) where organization_type = 'platform_owner' and status <> 'archived';
create table platform.companies (id uuid primary key default gen_random_uuid(), organization_id uuid not null references platform.organizations(id) on delete restrict, code text not null, name text not null, slug text not null, is_default boolean not null default false, status text not null default 'active' check (status in ('pending','active','suspended','archived')), metadata jsonb not null default '{}', created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique (organization_id, code), unique (organization_id, slug), unique (organization_id, id));
create unique index one_default_company_per_org on platform.companies (organization_id) where is_default and status <> 'archived';
create table iam.profiles (user_id uuid primary key references auth.users(id) on delete cascade, display_name text not null, phone_e164 text, avatar_path text, status text not null default 'active' check (status in ('pending','active','suspended','disabled')), locale text not null default 'en-KE', created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table iam.organization_memberships (id uuid primary key default gen_random_uuid(), organization_id uuid not null references platform.organizations(id) on delete cascade, user_id uuid not null references auth.users(id) on delete cascade, status text not null default 'active' check (status in ('invited','active','suspended','revoked')), joined_at timestamptz, created_by uuid references auth.users(id) on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique (organization_id, user_id));
create table iam.company_memberships (id uuid primary key default gen_random_uuid(), organization_membership_id uuid not null references iam.organization_memberships(id) on delete cascade, organization_id uuid not null references platform.organizations(id) on delete cascade, company_id uuid not null references platform.companies(id) on delete cascade, status text not null default 'active' check (status in ('active','suspended','revoked')), created_by uuid references auth.users(id) on delete set null, created_at timestamptz not null default now(), updated_at timestamptz not null default now(), unique (organization_membership_id, company_id));
create trigger organizations_updated_at before update on platform.organizations for each row execute function private.set_updated_at();
create trigger companies_updated_at before update on platform.companies for each row execute function private.set_updated_at();
create trigger profiles_updated_at before update on iam.profiles for each row execute function private.set_updated_at();
create trigger organization_memberships_updated_at before update on iam.organization_memberships for each row execute function private.set_updated_at();
create trigger company_memberships_updated_at before update on iam.company_memberships for each row execute function private.set_updated_at();
commit;
